-- Loads the sample e-commerce dataset. Run scripts/schema.sql first.
-- Safe to re-run: TRUNCATEs and reloads deterministically (same random
-- seed every time), so demo data stays consistent across environments.
-- Generated by scripts/generate_seed_data.py - edit that, not this file directly.

BEGIN;

TRUNCATE order_items, orders, products, customers RESTART IDENTITY CASCADE;





SELECT setval('orders_id_seq', (SELECT MAX(id) FROM orders));
SELECT setval('order_items_id_seq', (SELECT MAX(id) FROM order_items));

COMMIT;
